from xitong_yonghu
where id = #{id}

select id from laoren_xinxi where xingming = #{laorenXingming}
and lianxi_dianhua = #{lianxiDianhua}
and ruzhu_zhuangtai != '已删除' order by id desc limit 1

select id
from jiashu_xinxi
where laoren_id = #{laorenId}
  and shouji = #{shouji}
limit 1

